  "settings.commandline.trustCaution": "W tym trybie każdy program na dozwolonych maszynach, w tym działające tu agenty, może sterować Polyth w Twoim imieniu, łącznie z zatwierdzaniem działań agenta. Żądania przesyłane przez reverse proxy lub z przeglądarki nigdy nie są zaufane. „Sieć prywatna” oznacza adresy sieci lokalnej (10.x, 172.16–31.x, 192.168.x), a nie zakresy VPN lub nakładkowe.",
