  "shellintro.kicker": "Przewodnik po interfejsie",
  "shellintro.stepCount": "{step} z {total}",
  "shellintro.steps": "Kroki przewodnika",
  "shellintro.goToStep": "Przejdź do kroku {step} z {total}",
  "shellintro.start": "Oprowadź mnie",
  "shellintro.skip": "Pomiń przewodnik",
  "shellintro.finish": "Zaczynamy",
  "shellintro.menuEntry": "Przewodnik po interfejsie",
  "shellintro.addProjectNow": "Dodaj projekt teraz",
  "shellintro.addProjectResumeNote": "Wycieczka będzie kontynuowana, gdy skończysz.",
  "shellintro.projectReadyTitle": "Twój projekt jest gotowy",
  "shellintro.projectReadyBody": "Oto on. Dopóki jest wybrany, nowe czaty widzą jego pliki i mogą na nich pracować. Kliknij projekt na tej liście, aby przełączać się między projektami.",
  "shellintro.projectReadyPhoneBody": "Jest już w tym menu. Dopóki jest wybrany, nowe czaty widzą jego pliki i mogą na nich pracować. Dotknij tutaj w dowolnej chwili, aby zmienić projekt.",
  "shellintro.openAppearance": "Otwórz Wygląd",
  "shellintro.welcomeTitle": "Witaj w Polyth",
  "shellintro.welcomeBody": "Możesz zacząć od razu — nie ma nic do konfigurowania i nie da się niczego zepsuć. Ta minutowa wycieczka pokaże Ci, gdzie pisać, gdzie są przechowywane Twoje czaty i jak później coś zmienić.",
  "shellintro.startTitle": "Zacznij od razu tutaj",
  "shellintro.startBody": "Napisz własnymi słowami, czego potrzebujesz — pytanie, zadanie albo szkic — i wyślij. Odpowiedź pojawi się właśnie tutaj. Twoje czaty widzisz tylko Ty.",
  "shellintro.projectsTitle": "Czaty i projekty",
  "shellintro.projectsBody": "Tu przechowywane są wszystkie Twoje czaty, więc możesz wrócić do każdego z nich. Projekty, które dodasz później, też pojawią się tutaj, każdy z własnymi czatami. Mała kropka oznacza, że asystent pracuje lub czeka na Twoją odpowiedź.",
  "shellintro.addProjectTitle": "Projekty — gdy będą potrzebne",
  "shellintro.addProjectBody": "Nie jest potrzebny na start. Projekt to po prostu folder z Twoimi plikami — dokumentami, zdjęciami, stroną internetową lub kodem. Dodaj go, a asystent będzie mógł otwierać i edytować te pliki na Twoją prośbę. (Programiści mogą też połączyć repozytorium Git lub inny komputer przez SSH.)",
  "shellintro.topRailTitle": "Narzędzia u góry",
  "shellintro.topRailBody": "Przyciski do Twoich narzędzi. Każde otwiera się obok czatu, więc rozmowa zostaje na widoku.",
  "shellintro.rightRailTitle": "Więcej narzędzi z boku",
  "shellintro.rightRailBody": "Więcej narzędzi, także dodatki, które zainstalujesz. Każde otwiera się jako panel boczny; przeciągnij jego krawędź, aby go poszerzyć.",
  "shellintro.toolsTitle": "Narzędzia",
  "shellintro.dragTitle": "Ustaw przyciski, gdzie chcesz",
  "shellintro.dragBody": "Przeciągnij przycisk, aby przesunąć go wzdłuż jego paska lub na inny. Aby go usunąć, odciągnij go i puść — później możesz dodać go z powrotem. Na ekranie dotykowym najpierw przytrzymaj.",
  "shellintro.customizeTitle": "Funkcje po swojemu",
  "shellintro.customizeBody": "Otwórz menu, na które wskazuje strzałka, i włącz „Tryb edycji”: na każdej części ekranu pojawi się ołówek, dzięki któremu dodasz, usuniesz lub przesuniesz przyciski i widżety. Resztę znajdziesz w Ustawieniach: asystenci i modele AI, dodatki (pakiety) oraz skróty klawiszowe.",
  "shellintro.appearanceTitle": "Wygląd po swojemu",
  "shellintro.appearanceBody": "W Ustawieniach → Wygląd wybierzesz kolory, jasny lub ciemny tryb, rozmiar tekstu, czcionki, tapetę i więcej. Każdy projekt może też mieć własną ikonę.",
  "shellintro.projectsPhoneTitle": "Czaty i projekty",
  "shellintro.projectsPhoneBody": "Dotknij tutaj, aby zobaczyć swoje czaty. Projekty, które dodasz później, też pojawią się tutaj. Mała kropka oznacza, że asystent pracuje lub czeka na Twoją odpowiedź.",
  "shellintro.addProjectPhoneBody": "Nie jest potrzebny na start. Projekt to po prostu folder z Twoimi plikami — dokumentami, zdjęciami, stroną internetową lub kodem. Przycisk + w tym menu dodaje go; wtedy asystent może otwierać i edytować te pliki na Twoją prośbę.",
  "shellintro.toolsPhoneTitle": "Narzędzia",
  "shellintro.toolsPhoneBody": "Tu są Twoje narzędzia. Każde otwiera się na pełnym ekranie; dotknij „Wstecz”, aby wrócić do czatu.",
  "shellintro.customizePhoneBody": "Na komputerze „Tryb edycji” w Twoim menu pozwala dodawać, usuwać i przesuwać przyciski. Tutaj też w Ustawieniach wybierzesz asystentów i modele AI, dodatki (pakiety) i więcej.",
  "composer.manageHarnesses": "Zarządzaj silnikami",
  "packages.onboarding.tours.installed.modelsComeFromHarnesses": "Modele pochodzą z Twoich harnessów",
  "packages.onboarding.tours.installed.polythTalksToModelsThroughHarnesses": "Polyth rozmawia z modelami przez harnessy agentów. Darmowe modele OpenCode działają bez konta. Wolisz Claude Code, Codex lub innego agenta? Zainstaluj i skonfiguruj ulubione na stronie Harnesses — to opcjonalne.",
  "packages.onboarding.tours.installed.openHarnesses": "Otwórz Harnesses",
